-- Generated by pwc2dbt from PowerCenter mapping m_FL_JS_STAGING_FULL, target STG_SUPPLIES.

with

sq_raw_supplies as (
    -- Source Qualifier SQ_RAW_SUPPLIES
    select
        raw_supplies.id,
        raw_supplies.name,
        raw_supplies.cost,
        raw_supplies.perishable,
        raw_supplies.sku
    from {{ source('raw', 'raw_supplies') }} as raw_supplies
),

sq_raw_products1 as (
    -- Source Qualifier SQ_RAW_PRODUCTS1
    select
        raw_products1.sku,
        raw_products1.name,
        raw_products1.type,
        raw_products1.price,
        raw_products1.description
    from {{ source('raw', 'raw_products') }} as raw_products1
),

jnr_supplies_products as (
    -- Joiner JNR_SUPPLIES_PRODUCTS
    -- Normal Join (master sq_raw_products1, detail sq_raw_supplies)
    select
        sq_raw_supplies.id,
        sq_raw_supplies.name,
        sq_raw_supplies.cost,
        sq_raw_supplies.perishable,
        sq_raw_supplies.sku,
        sq_raw_products1.sku as sku1
    from sq_raw_supplies
        inner join sq_raw_products1
            on sq_raw_products1.sku = sq_raw_supplies.sku
),

exp_supplies as (
    -- Expression EXP_SUPPLIES
    select
        jnr_supplies_products.id as supply_id,
        jnr_supplies_products.name as supply_name,
        jnr_supplies_products.cost as supply_cost_cents,
        jnr_supplies_products.cost / 100 as supply_cost,
        case when jnr_supplies_products.perishable = 'Y' or jnr_supplies_products.perishable = '1' then 1 else 0 end as is_perishable,
        jnr_supplies_products.sku as product_id
    from jnr_supplies_products
)

select
    exp_supplies.supply_id,
    exp_supplies.supply_name,
    exp_supplies.supply_cost_cents,
    exp_supplies.supply_cost,
    exp_supplies.is_perishable,
    exp_supplies.product_id
from exp_supplies
